function notify(message){$('#toast').textContent=message;$('#toast').style.opacity='1';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').style.opacity='0',3000);}
function commit(next,message){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(next));state=next;render();if(message)notify(message);return true;}catch{notify('저장 공간이 부족해요. 작은 사진을 사용하거나 기존 기록을 확인해 주세요.');return false;}}
