let activeFlow=null,flowReplay=false;
history.replaceState({...history.state,baeminFlow:null},'',location.pathname+location.search);
function releaseFlow(){const d=$('#dialog');if(d.open)d.close();d.classList.remove('commerce-screen','order-detail-screen','benefit-dialog');$('.phone').classList.remove('flow-open');for(const selector of ['#app-header','#page','#navigation'])$(selector).inert=false;activeFlow=null;}
function showDialogContent(title,body,flow){const d=$('#dialog'),orderDetail=flow&&activeFlow?.type==='order';d.classList.remove('benefit-dialog');d.classList.toggle('order-detail-screen',orderDetail);d.innerHTML=`<div class="dialog-head">${flow?'<button class="flow-back" data-action="flow-back" aria-label="이전 화면으로">‹</button>':''}<h2 id="dialog-title">${esc(title)}</h2>${orderDetail?`<button class="detail-header-cart" data-action="cart" aria-label="장바구니">${icon('cart')}${cart?.lines.length?`<span class="cart-dot">${cart.lines.reduce((n,l)=>n+l.quantity,0)}</span>`:''}</button>`:flow?'':'<button class="close" data-action="close" aria-label="닫기">×</button>'}</div><div class="dialog-body">${body}</div>`;}

function dialog(title,body){if(activeFlow){releaseFlow();history.replaceState({...history.state,baeminFlow:null},'',location.pathname+location.search);}const d=$('#dialog');if(d.open)d.close();document.body.append(d);d.classList.remove('commerce-screen');showDialogContent(title,body,false);if(!d.open)d.showModal();}
function flowDialog(type,id,title,body){const descriptor={type,id};const previous=activeFlow,key=type+':'+(id||'');if(!flowReplay&&(!previous||previous.type+':'+(previous.id||'')!==key)){const url=location.pathname+location.search+'#'+type+(id?'/'+encodeURIComponent(id):'');history.pushState({...history.state,baeminFlow:descriptor},'',url);}const d=$('#dialog');if(d.open&&!d.classList.contains('commerce-screen'))d.close();$('.phone').append(d);d.classList.add('commerce-screen');$('.phone').classList.add('flow-open');for(const selector of ['#app-header','#page','#navigation'])$(selector).inert=true;activeFlow=descriptor;showDialogContent(title,body,true);if(!d.open)d.show();d.scrollTop=0;}
function closeDialog(){photoGeneration++;analysisPending=false;const wasFlow=!!activeFlow;releaseFlow();if(wasFlow)history.replaceState({...history.state,baeminFlow:null},'',location.pathname+location.search);}
addEventListener('popstate',e=>{const target=e.state?.baeminFlow;flowReplay=true;try{if(target?.type==='menu')openMenu(target.id);else if(target?.type==='cart')openCart();else if(target?.type==='order')openDetail(target.id);else{releaseFlow();render();}}finally{flowReplay=false;}});
function readForm(form){return Object.fromEntries(new FormData(form).entries());}
function field(label,name,type,value,attrs=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;}
