function dailyMealSummary(totals){const meals=dailyMeals(state,state.selectedDate,filter).records;return `<button class="daily-total daily-meal-summary" data-action="date" data-date="${state.selectedDate}" aria-label="기록한 식사 ${totals.count}끼, 총 ${Math.round(totals.calories).toLocaleString()} kcal, 음식 기록 보기"><span class="daily-summary-top"><span>이날의 한 끼</span><b>${totals.count}끼</b></span><span class="daily-energy-heading">기록한 식사의 총 열량</span><strong class="daily-energy-value">${Math.round(totals.calories).toLocaleString()} <small>kcal</small></strong><span class="daily-summary-bottom"><span class="daily-meal-photos" aria-hidden="true">${meals.slice(0,3).map(m=>thumb(m)).join('')}${meals.length>3?`<i>+${meals.length-3}</i>`:''}</span><span>음식별 기록 보기 ${icon('chevron')}</span></span></button>`;}

