 const entries=entriesFor(state.selectedDate),totals=totalsFor(state,state.selectedDate,filter),d=new Date(state.selectedDate+'T12:00:00Z');
 return `<div class="original-filters"><button data-action="search">${icon('search')} ${searchQuery?esc(searchQuery):'검색'}</button><button data-action="period">조회 기간 ${icon('down')}</button><button data-action="status-filter">주문 상태·정보 ${icon('down')}</button></div><div class="filters" aria-label="내역 필터">${[['all','전체'],['delivery','배달 주문'],['photo','사진 기록'],...(filter==='delivered'?[['delivered','배달 완료']]:filter==='cancelled'?[['cancelled','전체 취소']]:[])].map(([id,name])=>`<button data-action="filter" data-filter="${id}" class="${filter===id?'active':''}">${name}</button>`).join('')}${searchQuery?'<button data-action="clear-search">검색 해제 ×</button>':''}</div>${activeCards()}${calendar()}${reportPreview()}<div class="section-heading"><h3>${d.getUTCMonth()+1}월 ${d.getUTCDate()}일 ${['일','월','화','수','목','금','토'][d.getUTCDay()]}요일</h3><span>${entries.length}개 내역</span></div>${totals.count&&!searchQuery?`${dailyMealSummary(totals)}`:''}${entries.length?entries.map(e=>e.type==='order'?orderCard(e.order):recordCard(e.record)).join(''):`<div class="empty">${icon('receipt')}<br>${filter==='all'?'이날의 주문·음식 기록이 없어요.':'선택한 필터에 맞는 내역이 없어요.'}<br>홈에서 주문하거나 날짜를 눌러 한 끼를 남겨보세요.</div>`}`;
