function myPage(){const today=kstDate(new Date()),coupons=state.coupons.filter(c=>couponStatus(c,today)==='available'),unread=coupons.filter(c=>!c.seenAt).length;return `<section class="profile-block"><button class="survey-strip" data-action="profile-note">ⓘ 배민의 음식주문 경험, 어떠셨나요? ${icon('chevron')}</button><div class="avatar" aria-label="프로필"><img src="/assets/captured/profile-mascot.png" alt="분홍 프로필 캐릭터"></div><div class="profile-name"><h3>민수</h3><button data-action="profile-note">꾸미기</button></div></section><div class="my-group wallet"><button class="my-row wallet-coupon-link" data-action="coupons"><b>쿠폰함</b><strong>${coupons.length}개 ${icon('chevron')}</strong></button><button class="coupon-preview" data-action="coupons">${unread?`아직 확인하지 않은 보유 쿠폰 ${unread}개`:'보유 쿠폰의 사용 조건을 확인해요'} </button><div class="my-row"><b>포인트</b><strong>${pointsBalance(state).toLocaleString()}P</strong></div><div class="my-row"><b>선물함</b><strong>0원</strong></div><div class="my-row"><div><b>배민페이</b><small>결제수단을 간편하게 관리해요</small></div><button data-action="payment-note">결제수단 관리</button></div></div><div class="my-group single"><button class="my-link" data-action="school-note"><b>우리 학교 급식표</b>${icon('chevron')}</button></div><div class="my-group favorite-preview"><button class="my-link" data-action="tab" data-tab="favorites"><b>찜한 가게·상품</b>${icon('chevron')}</button><div class="favorite-tiles">${SHOPS.filter(s=>state.favorites.includes(s.id)).map(s=>`<button data-action="tab" data-tab="favorites">${thumb(CATALOG.find(m=>m.shopId===s.id))}<small>${s.name}</small></button>`).join('')||'<p>마음에 드는 가게를 찜해보세요.</p>'}</div></div><div class="my-group"><button class="my-link" data-action="reviews"><b>리뷰관리</b><span>${state.reviews.length}개 ${icon('chevron')}</span></button><button class="my-link" data-action="tab" data-tab="orders"><b>나의 주문 캘린더</b>${icon('chevron')}</button></div>`;}
