function marketLogos(){return `<div class="market-logos">${[['bmart','B마트','B','mint'],['cu-market','CU','CU','cu'],['gs-market','GS25','GS25','gs'],['fresh-market','동네마트','싱싱','fresh']].map(([id,name,logo,cls])=>`<button data-action="market-store" data-id="${id}"><span class="market-logo ${cls} ${['bmart','cu-market','gs-market'].includes(id)?'market-source':''}">${['bmart','cu-market','gs-market'].includes(id)?`<img src="/assets/captured/market-${({bmart:'bmart','cu-market':'cu','gs-market':'gs'})[id]}.png?v=${CAPTURED_VERSION}" alt="" aria-hidden="true">`:logo}</span><b>${name}</b></button>`).join('')}<button data-action="market-category" data-category="과일·채소"><span class="market-logo fruit">🍎</span><b>과일·채소</b></button></div>`;}
function homePage(){if(shopView)return storePage(shopView);const shops=SHOPS.filter(s=>!s.service&&s.open&&(homeCategory==='전체'||s.category===homeCategory)&&(!foodQuery||[s.name,s.category,...MENUS.filter(m=>m.shopId===s.id).map(m=>m.name)].join(' ').includes(foodQuery)));const menus=MENUS.filter(m=>shops.some(s=>s.id===m.shopId));return `<div class="delivery-home"><div class="home-services"><button class="${orderService==='delivery'?'selected':''}" data-action="delivery-mode" data-mode="delivery">음식배달</button><button class="${orderService==='pickup'?'selected':''}" data-action="delivery-mode" data-mode="pickup">픽업</button><button data-action="tab" data-tab="shopping">장보기·쇼핑</button><button data-action="gifts">선물하기</button><button data-action="benefits">혜택모아보기</button></div><div class="food-categories">${CATEGORIES.slice(1).map(([name,emoji])=>`<button data-action="category" data-category="${name}" class="${homeCategory===name?'selected':''}"><span>${categoryImage(name,emoji)}</span><b>${name}</b></button>`).join('')}<button data-action="category" data-category="전체" class="${homeCategory==='전체'?'selected':''}"><span class="all-food"><img src="/assets/captured/category-single.png?v=20261026-crop-v2" alt="" aria-hidden="true"></span><b>전체보기</b></button></div><button class="expand-delivery" data-action="category" data-category="전체">음식배달에서 더보기 ${icon('chevron')}</button>${marketLogos()}<button class="home-promo" data-action="tab" data-tab="shopping"><div><small>오늘의 한 끼를 준비하는 방법</small><h3>신선한 재료로,<br>우리 집이 맛집으로</h3><p>B마트와 동네마트에서 재료를 골라요</p><span class="home-promo-link">장보기 둘러보기 ${icon('chevron')}</span></div><span class="home-promo-visual" aria-hidden="true"><span class="promo-food">${thumb({kind:'salmon',name:'연어 포케'})}</span><span class="promo-calendar"><b>오늘의 장보기</b><i>✓ ✓</i><i>✓ <em>♥</em></i></span></span></button><section class="discovery-section"><div class="section-heading"><h3>${foodQuery?`‘${esc(foodQuery)}’ 검색 결과`:homeCategory==='전체'?'지금 생각나는 한 그릇':homeCategory+' 맛집'}</h3>${homeCategory!=='전체'||foodQuery?'<button data-action="clear-food">전체보기 ›</button>':'<small>배달팁 0원</small>'}</div><div class="discovery-grid">${(homeCategory==='전체'&&!foodQuery?shops.map(s=>menus.find(m=>m.shopId===s.id)).filter(Boolean).slice(0,6):menus.slice(0,6)).map(menuTile).join('')||'<div class="empty">검색 결과가 없어요.</div>'}</div></section><section class="home-stores"><div class="section-heading"><h3>우리 동네 맛집</h3><span>${shops.length}개</span></div>${shops.map(shopCard).join('')}</section></div>`;}
