function shoppingOrdersPage(){const orders=state.orders.filter(o=>o.service==='shopping');return `<div class="section-heading"><h3>장보기·쇼핑 주문내역</h3><span>${orders.length}개</span></div>${orders.length?orders.map(orderCard).join(''):'<div class="empty">아직 장보기 주문내역이 없어요.<br>필요한 상품을 장바구니에 담아보세요.</div>'}`;}
